using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;
    private Task? serving;

    public HttpPaymentGatewayTests()
    {
        var port = GetFreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        var captured = Serve(200, """{"status":"approved"}""");

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var request = await captured;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        Serve(200, """{"status":"approved"}""");

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        Serve(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Serve(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task Anything_other_than_an_approved_status_is_never_treated_as_approved(string body)
    {
        Serve(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        Serve(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        Serve(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_an_error()
    {
        Serve(200, "<html>gateway</html>");

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

    private Task<CapturedRequest> Serve(int status, string body)
    {
        var task = Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            var request = context.Request;
            string received;
            using (var reader = new StreamReader(request.InputStream, request.ContentEncoding))
                received = await reader.ReadToEndAsync();
            var captured = new CapturedRequest(request.HttpMethod, request.Url!.AbsolutePath, request.ContentType ?? "", received);

            var bytes = Encoding.UTF8.GetBytes(body);
            context.Response.StatusCode = status;
            context.Response.ContentType = "application/json";
            context.Response.ContentLength64 = bytes.Length;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
            return captured;
        });
        serving = task;
        return task;
    }

    private static int GetFreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
        try { serving?.Wait(TimeSpan.FromSeconds(2)); } catch (AggregateException) { }
    }

    private sealed record CapturedRequest(string Method, string Path, string ContentType, string Body);
}
